final class ContextSignedWitnessCandidateMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 static Snapshot bind(boolean x,String s)throws Exception{return ContextSignedWitnessNativeMatrix.bind(x,s);}
 static Policy policy(){return new Policy(ContextSignedWitnessNativeMatrix.policy(),1000,WORK,500000);}
 static Receipt yes(Snapshot x,List<Snapshot> fs,String text,Policy p){Result r=ContextSignedWitnessNativeCandidate.run(x,fs,text,p);require(r.status==ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED&&r.output!=null&&r.rejection==null,r.phase+": "+r.reason);Receipt a=r.output;require(a.artifact.base==x&&a.branch.x==a.artifact.staged&&a.originals.get(a.artifact.candidate).equals(a.artifact.candidate)&&a.oppositions.isEmpty(),"exact staged owner and NEW candidate Source");ContextSignedWitnessNativeCandidateAudit.check(a,x,fs,text,p,WORK,1);require(true,"fresh semantic and whole signed ingress audit capacity1");return a;}
 static Set<Source> translated(Receipt r,org.kanger.ContextProductionCapture.Support p){return ContextSignedWitnessNativeCandidateAudit.translate(p,r.originals,ContextGroundProductionRounds.budget(WORK));}
 static void positive()throws Exception{
  ContextUniversalNativeCandidateMatrix.Fixture old=new ContextUniversalNativeCandidateMatrix.Fixture(true,"!$u seed(u)&&~blocked(u);"),consumer=new ContextUniversalNativeCandidateMatrix.Fixture(false,"!@u seed(u)->ready(u);");Snapshot x=old.snapshot,a=consumer.snapshot;Policy p=policy();Receipt r=yes(x,Collections.singletonList(a),"!extra(2);",p);Source original=x.primary.get(0).source,rebased=r.artifact.rebased.get(original);require(!rebased.equals(original)&&r.originals.get(rebased).equals(original),"old signed X bundle genuinely rebased");Item ready=r.branch.termination.result.output.current().packet.items.stream().filter(i->i.atom.predicate.equals("ready")).findFirst().get();require(ready.atom.arguments.get(0).origin.source.equals(rebased)&&!ready.atom.arguments.get(0).origin.source.equals(original),"Origin remains in actual staged frame, metadata translation never rewrites token");require(ready.proofs.stream().anyMatch(s->translated(r,s).equals(new HashSet<>(Arrays.asList(original,a.primary.get(0).source)))),"exact signed old-X plus physical foreign Source support");old.unchanged();consumer.unchanged();require(true,"both caller inventories fingerprint unchanged");
  Snapshot anchor=bind(true,"!anchor(1);"),signed=bind(false,"!$u seed(u)&&~blocked(u);");Receipt rule=yes(anchor,Collections.singletonList(signed),"!@u seed(u)->~blocked(u);",p);require(rule.branch.termination.result.output.current().packet.items.stream().filter(i->i.atom.predicate.equals("blocked")&&!i.atom.positive).flatMap(i->i.proofs.stream()).anyMatch(s->s.sources.contains(rule.artifact.candidate)&&s.sources.contains(signed.primary.get(0).source)),"candidate rule participates in actual negative witness production");System.out.println("SIGNED_CANDIDATE_POSITIVE oldSignedOriginsRebasedNotRewritten=true candidateRuleActualProduct=true callersUnchanged=true");
 }
 static void witness()throws Exception{Snapshot x=bind(true,"!anchor(1);"),a=bind(false,"!@u seed(u)->ready(u);");Policy p=policy();String text="!$u seed(u)&&~blocked(u);";Receipt r=yes(x,Collections.singletonList(a),text,p);Item ready=r.branch.termination.result.output.current().packet.items.stream().filter(i->i.atom.predicate.equals("ready")).findFirst().get();require(ready.atom.arguments.get(0).origin.source.equals(r.artifact.candidate)&&ready.atom.arguments.get(0).origin.binder==0,"NEW signed candidate owns witness Origin");require(ready.proofs.stream().anyMatch(s->s.depth==1&&translated(r,s).equals(new HashSet<>(Arrays.asList(r.artifact.candidate,a.primary.get(0).source)))),"exact candidate bundle+consumer Source depth1");require(r.artifact.staged.primary.size()==x.primary.size()+1&&r.originals.size()==3,"complete old/new/foreign primary occurrence coverage");System.out.println("SIGNED_CANDIDATE_WITNESS actualSignedCandidate=true candidateOwnedOrigin=true exactProofDepth=true");}
 static Receipt refuted(Snapshot x,List<Snapshot> fs,String text,Policy p,boolean uses){Result r=ContextSignedWitnessNativeCandidate.run(x,fs,text,p);require(r.status==ContextSignedWitnessNativeBranch.Status.REFUTED&&r.output==null&&r.rejection!=null,r.phase+": "+r.reason);Receipt a=r.rejection;require(!a.oppositions.isEmpty()&&a.oppositions.values().stream().flatMap(List::stream).allMatch(v->v.usesCandidate==uses&&v.proof.support.sources.contains(a.artifact.candidate)==uses&&v.originalSources.contains(a.artifact.candidate)==uses),"actual proof membership, never candidate presence alone");ContextSignedWitnessNativeCandidateAudit.check(a,x,fs,text,p,WORK,1);require(true,"fresh attributed rejection audit");return a;}
 static void refutations()throws Exception{Policy p=policy();Snapshot x=bind(true,"!anchor(1);"),signed=bind(false,"!$u seed(u)&&~blocked(u);");Receipt initial=refuted(x,Collections.singletonList(signed),"!@u seed(u)->blocked(u);",p,true);require(initial.branch.initialRejection!=null&&initial.oppositions.values().stream().flatMap(List::stream).allMatch(v->v.originalSources.equals(new HashSet<>(Arrays.asList(initial.artifact.candidate,signed.primary.get(0).source)))),"exact initial signed candidate+bundle empty proof");Snapshot yes=bind(false,"!p(1);"),no=bind(false,"!~p(1);");Snapshot group=ContextProductionNativeBinding.trusted("candidate-existing",Arrays.asList(yes,no),WORK);Receipt existing=refuted(x,Collections.singletonList(group),"!extra(2);",p,false);require(existing.oppositions.values().stream().flatMap(List::stream).allMatch(v->v.originalSources.equals(new HashSet<>(Arrays.asList(yes.primary.get(0).source,no.primary.get(0).source)))),"preexisting foreign-only contradiction never blamed on candidate");
  Snapshot a=bind(false,"!p(1); !left(1); !$u aa(u)&&~aside(u);"),b=bind(false,"!~p(1); !right(1); !$u bb(u)&&~bside(u);");Receipt later=refuted(x,Arrays.asList(a,b),"!@u left(u)&&right(u)->p(u);",p,true);require(later.branch.initialRejection==null&&later.branch.termination!=null&&later.oppositions.values().stream().flatMap(List::stream).anyMatch(v->v.originalSources.size()==4),"post-barrier four-Source candidate contradiction");System.out.println("SIGNED_CANDIDATE_REFUTATION initialLaterAndPreexisting=true completeProofAttribution=true noCausalNecessityClaim=true");}
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}require(failed,why);}
 static void no(Result r,String why){require(r.status==ContextSignedWitnessNativeBranch.Status.INCOMPLETE&&r.output==null&&r.rejection==null,why+": atomic no-prefix refusal");}
 static void boundary()throws Exception{Snapshot x=bind(true,"!anchor(1);"),a=bind(false,"!$u seed(u)&&~blocked(u);");Policy p=policy();for(String s:Arrays.asList("?p(1);","!a(1); !b(1);","!anchor(1);","!@u p(u)||q(u);"))no(ContextSignedWitnessNativeCandidate.run(x,Collections.singletonList(a),s,p),"query/script/duplicate/unsupported assertion");no(ContextSignedWitnessNativeCandidate.run(x,Collections.singletonList(a),"!extra(2);",new Policy(p.branch,1000,1,500000)),"preparation work");no(ContextSignedWitnessNativeCandidate.run(x,Collections.singletonList(a),"!extra(2);",new Policy(p.branch,1,WORK,500000)),"complete preparation row bound");no(ContextSignedWitnessNativeCandidate.run(x,Arrays.asList(a,a),"!extra(2);",p),"physical alias");reject(()->new Policy(p.branch,1000,WORK,0),"invalid event bound");System.out.println("SIGNED_CANDIDATE_BOUNDARY completePreparationAndShapeRequired=true noPartialEvidence=true");}
 static void integrity()throws Exception{Snapshot x=bind(true,"!anchor(1);"),a=bind(false,"!$u seed(u)&&~blocked(u);");List<Snapshot> fs=Collections.singletonList(a);Policy p=policy();String text="!extra(2);";Receipt r=yes(x,fs,text,p),other=yes(x,fs,text,p);reject(()->ContextSignedWitnessNativeCandidateAudit.check(r,x,fs,"!extra(3);",p,WORK,64),"different request");reject(()->ContextSignedWitnessNativeCandidateAudit.check(r,x,fs,text,policy(),WORK,64),"different policy");reject(()->ContextSignedWitnessNativeCandidateAudit.check(r,x,fs,text,p,1,64),"fresh small budget");mutate(r,r.artifact,"rebased",Collections.emptyMap(),x,fs,text,p);mutate(r,r.artifact,"candidate",r.artifact.rebased.values().iterator().next(),x,fs,text,p);mutate(r,r.artifact,"identity",UUID.randomUUID(),x,fs,text,p);mutate(r,r,"originals",Collections.singletonMap(r.artifact.candidate,r.artifact.candidate),x,fs,text,p);mutate(r,r,"branch",other.branch,x,fs,text,p);mutate(r,r.artifact,"statement","!forged(9);",x,fs,"!forged(9);",p);ContextSignedWitnessNativeCandidateAudit.check(r,x,fs,text,p,WORK,1);require(true,"restored ledger freshly audits");reject(()->r.originals.clear(),"immutable Source translation");
  Receipt rejected=refuted(x,fs,"!@u seed(u)->blocked(u);",p,true);mutate(rejected,rejected,"oppositions",Collections.emptyMap(),x,fs,"!@u seed(u)->blocked(u);",p);Attribution v=rejected.oppositions.values().iterator().next().get(0);mutate(rejected,v,"usesCandidate",false,x,fs,"!@u seed(u)->blocked(u);",p);mutate(rejected,v,"originalSources",Collections.emptySet(),x,fs,"!@u seed(u)->blocked(u);",p);ContextSignedWitnessNativeCandidateAudit.check(rejected,x,fs,"!@u seed(u)->blocked(u);",p,WORK,1);require(true,"restored complete rejection attribution audits");System.out.println("SIGNED_CANDIDATE_INTEGRITY requestSemanticsNotMetadata=true otherTrialCannotDonate=true exactTranslationAndAttribution=true");}
 static void mutate(Receipt r,Object o,String field,Object value,Snapshot x,List<Snapshot> fs,String text,Policy p)throws Exception{Object old=ContextSignedWitnessBarrierMatrix.replace(o,field,value);try{reject(()->ContextSignedWitnessNativeCandidateAudit.check(r,x,fs,text,p,WORK,64),"tampered "+field);}finally{ContextSignedWitnessBarrierMatrix.replace(o,field,old);}}
}
